import os
import ast

def inspect_functions():
    for root, dirs, files in os.walk('app'):
        for file in files:
            if not file.endswith('.py') or file == 'auth.py':
                continue
            path = os.path.join(root, file)
            with open(path, 'r', encoding='utf-8') as f:
                content = f.read()
            if 'legacy_auth' not in content:
                continue

            # Parse AST to find functions calling legacy_auth
            try:
                tree = ast.parse(content)
            except Exception as e:
                print(f"Error parsing {path}: {e}")
                continue

            for node in ast.walk(tree):
                if isinstance(node, ast.FunctionDef):
                    # Check if legacy_auth is in this function
                    func_str = ast.get_source_segment(content, node)
                    if func_str and 'legacy_auth' in func_str:
                        print(f"File: {path}, Function: {node.name}")
                        print("---")
                        print(func_str)
                        print("====================================")

if __name__ == '__main__':
    inspect_functions()

